import pandas as pd
import plotly.express as px
import streamlit as st

from src.database import load_experiments, save_experiment
from src.evaluator import detect_fault, evaluate_configuration
from src.simulator import FAULT_TYPES, simulate_machine

st.set_page_config(
    page_title="SensorScout",
    page_icon="🔍",
    layout="wide",
)

st.title("SensorScout")
st.caption(
    "Explore simulated machine faults and compare sensor layouts. "
    "These readings are generated by a simplified simulator."
)

# Sidebar controls
with st.sidebar:
    st.header("Simulation settings")

    fault_type = st.selectbox(
        "Fault type",
        FAULT_TYPES,
    )

    fault_position = st.slider(
        "Fault location",
        min_value=0,
        max_value=7,
        value=3,
    )

    sensor_positions = st.multiselect(
        "Sensor locations",
        options=list(range(8)),
        default=[0, 3, 6],
    )

    seed = st.number_input(
        "Random seed",
        min_value=0,
        value=42,
        step=1,
    )

    sampling_rate = st.selectbox(
        "Sampling rate per sensor (Hz)",
        options=[5, 10, 20],
        index=1,
    )

# Generate signals at a common underlying rate.
readings = simulate_machine(
    fault_type=fault_type,
    fault_position=fault_position,
    sampling_rate_hz=20,
    seed=int(seed),
)

if not sensor_positions:
    st.info("Select at least one sensor location in the sidebar.")
    st.stop()

# Display and detect using the selected sampling rate.
sampled_frames = []

for position in sensor_positions:
    sensor_readings = readings[
        readings["position"] == position
    ]

    step = 20 // sampling_rate
    sampled_frames.append(sensor_readings.iloc[::step])

visible = pd.concat(sampled_frames, ignore_index=True)
visible["sensor"] = "Position " + visible["position"].astype(str)

# Fault detection
st.subheader("Fault detection")

result = detect_fault(visible, sensor_positions)

if result["fault_detected"]:
    st.error("Fault detected in the selected sensors' readings.")
    st.write(
        f"First alarm: {result['first_alarm_s']:.1f} seconds"
    )
else:
    st.success("No fault detected in the selected sensors' readings.")

st.caption(
    "Demo alarm thresholds: vibration above 1.5 mm/s "
    "or temperature above 45°C. "
    "No alarm does not guarantee the machine is healthy."
)

# Signal metrics
left, right = st.columns(2)

with left:
    st.metric(
        "Maximum displayed vibration",
        f"{visible['vibration_rms_mm_s'].max():.2f} mm/s",
    )

with right:
    st.metric(
        "Maximum displayed temperature",
        f"{visible['temperature_c'].max():.1f} °C",
    )

# Signal charts
vibration_chart = px.line(
    visible,
    x="time_s",
    y="vibration_rms_mm_s",
    color="sensor",
    title="Vibration readings",
    labels={
        "time_s": "Time (s)",
        "vibration_rms_mm_s": "Vibration RMS (mm/s)",
        "sensor": "Sensor",
    },
)

temperature_chart = px.line(
    visible,
    x="time_s",
    y="temperature_c",
    color="sensor",
    title="Temperature readings",
    labels={
        "time_s": "Time (s)",
        "temperature_c": "Temperature (°C)",
        "sensor": "Sensor",
    },
)

if fault_type != "healthy":
    for chart in (vibration_chart, temperature_chart):
        chart.add_vline(
            x=40,
            line_dash="dash",
            annotation_text="Fault begins",
        )

st.plotly_chart(vibration_chart, width="stretch")
st.plotly_chart(temperature_chart, width="stretch")

with st.expander("View simulated readings"):
    st.dataframe(visible, width="stretch")

st.download_button(
    label="Download displayed readings as CSV",
    data=visible.to_csv(index=False),
    file_name=f"sensorscout_{fault_type}.csv",
    mime="text/csv",
)

# Configuration evaluation
st.divider()
st.subheader("Evaluate sensor layout")

st.write(
    "Test the selected sensor locations and sampling rate against "
    "24 faulty scenarios and 8 healthy scenarios."
)

st.caption(
    "This evaluation covers all fault types and locations, "
    "regardless of the fault selected for the charts."
)

config = {
    "sensor_positions": sensor_positions,
    "sampling_rates_hz": [
        sampling_rate for _ in sensor_positions
    ],
}

# Identify which settings produced the displayed result.
evaluation_key = (
    tuple(sensor_positions),
    sampling_rate,
    int(seed),
    "validation",
)

if st.button("Evaluate sensor layout"):
    with st.spinner("Testing sensor layout..."):
        evaluation = evaluate_configuration(
            config,
            scenario_set="validation",
            seed=int(seed),
        )

    st.session_state["evaluation"] = evaluation
    st.session_state["evaluation_key"] = evaluation_key
    st.session_state["saved_experiment_id"] = None

    try:
        experiment_id = save_experiment(evaluation)
        st.session_state["saved_experiment_id"] = experiment_id
    except (OSError, ValueError, TypeError) as error:
        st.error(
            f"Evaluation completed, but saving failed: {error}"
        )

# Keep the most recent result visible across normal interactions.
evaluation = st.session_state.get("evaluation")

if evaluation is not None:
    if st.session_state.get("evaluation_key") != evaluation_key:
        st.warning(
            "These results belong to your previous settings. "
            "Click Evaluate sensor layout to update them."
        )

    saved_id = st.session_state.get("saved_experiment_id")

    if saved_id:
        st.success(f"Experiment saved: {saved_id}")

    st.write("Evaluated configuration:", evaluation["config"])
    st.caption(
        f"Scenario set: {evaluation['scenario_set']} · "
        f"Seed: {evaluation['seed']}"
    )

    col1, col2, col3 = st.columns(3)

    col1.metric(
        "Fault recall",
        f"{evaluation['fault_recall']:.1%}",
    )

    precision = evaluation["precision"]

    col2.metric(
        "Precision",
        f"{precision:.1%}" if precision is not None else "N/A",
    )

    col3.metric(
        "False-alarm rate",
        f"{evaluation['false_alarm_rate']:.1%}",
    )

    col4, col5, col6 = st.columns(3)

    delay = evaluation["mean_detection_delay_s"]

    col4.metric(
        "Mean detection delay",
        f"{delay:.1f} s" if delay is not None else "N/A",
    )

    col5.metric(
        "Illustrative cost units",
        f"{evaluation['sensor_cost_units']:.0f}",
    )

    col6.metric(
        "Score",
        f"{evaluation['score']:.2f}",
    )

    st.write(
        f"Faults detected: {evaluation['faults_detected']} · "
        f"Faults missed: {evaluation['faults_missed']} · "
        f"False-alarm windows: "
        f"{evaluation['false_alarm_windows']}"
    )

    st.caption(
        "Detection delay includes detected faults only. "
        "The current score balances recall, false alarms, and cost; "
        "it also includes detection delay."
    )

    with st.expander("View individual scenario results"):
        st.dataframe(
            pd.DataFrame(evaluation["scenario_results"]),
            width="stretch",
        )


# -------------------------------------------------
# ATTACK MY DESIGN
# -------------------------------------------------

st.divider()
st.subheader("Attack My Design")

st.write(
    "Challenge your current sensor layout by searching "
    "for faults it misses or detects slowly."
)

st.caption(
    "This search tests the selected sensor layout against "
    "simulated validation scenarios."
)

if st.button("Find blind spots", key="attack_design_button"):
    with st.spinner("Searching for monitoring weaknesses..."):
        attack_result = evaluate_configuration(
            config,
            scenario_set="validation",
            seed=int(seed),
        )

    st.session_state["attack_result"] = attack_result

attack_result = st.session_state.get("attack_result")

if attack_result is not None:
    st.write(
        "Tested configuration:",
        attack_result["config"],
    )

    scenarios = [
        scenario
        for scenario in attack_result["scenario_results"]
        if scenario.get("fault_type") != "healthy"
    ]

    missed_faults = [
        scenario
        for scenario in scenarios
        if not scenario.get("detected", False)
    ]

    if missed_faults:
        st.error(
            f"Found {len(missed_faults)} missed fault scenarios."
        )

        st.dataframe(
            pd.DataFrame(missed_faults)[
                ["fault_type", "fault_position"]
            ],
            hide_index=True,
            use_container_width=True,
        )
    else:
        st.success(
            "No missed faults in the tested validation scenarios."
        )

    detected = [
        scenario
        for scenario in scenarios
        if scenario.get("detected", False)
        and scenario.get("detection_delay_s") is not None
    ]

    if detected:
        slowest = sorted(
            detected,
            key=lambda item: item["detection_delay_s"],
            reverse=True,
        )[:5]

        st.subheader("Slowest Detected Faults")

        st.dataframe(
            pd.DataFrame(slowest)[
                [
                    "fault_type",
                    "fault_position",
                    "detection_delay_s",
                ]
            ],
            hide_index=True,
            use_container_width=True,
        )

        worst = slowest[0]

        st.warning(
            f"Slowest scenario: {worst['fault_type']} "
            f"at position {worst['fault_position']}, "
            f"detected after "
            f"{worst['detection_delay_s']:.2f} seconds."
        )

    st.caption(
        "Results are based on simulated scenarios, "
        "not real factory equipment."
    )


# -------------------------------------------------
# AI OPTIMIZATION DASHBOARD
# -------------------------------------------------

from pathlib import Path
import json

from src.optimizer import run_optimization, BASELINE

st.divider()
st.header("SensorScout — Agent Optimization")

st.write(
    "SensorScout uses cooperating agents to identify "
    "monitoring weaknesses, test sensor configurations, "
    "and improve simulated fault detection performance."
)

st.caption(
    "Fast demo mode: rule-based Designer and "
    "simulation-guided targeted search. "
    "No external LLM requests are made."
)

# Optimization controls
rounds = st.slider(
    "Number of optimization rounds",
    min_value=1,
    max_value=10,
    value=2,
    key="optimization_rounds",
)

col_run, col_load = st.columns(2)

with col_run:
    run_clicked = st.button(
        "Run Agent Optimization",
        type="primary",
        use_container_width=True,
    )

with col_load:
    load_clicked = st.button(
        "Load Previous Optimization",
        use_container_width=True,
    )

if run_clicked:
    with st.spinner(
        "Agents are investigating blind spots "
        "and testing sensor configurations..."
    ):
        try:
            optimization_result = run_optimization(
                rounds=rounds,
                seed=42,
            )

            st.session_state["optimization_result"] = (
                optimization_result
            )

            output_path = Path("data/mock_run.json")
            output_path.parent.mkdir(
                parents=True,
                exist_ok=True,
            )

            output_path.write_text(
                json.dumps(optimization_result, indent=2)
            )

            st.success(
                "Optimization completed successfully!"
            )

        except Exception as error:
            st.error(
                f"Optimization failed: {error}"
            )

if load_clicked:
    output_path = Path("data/mock_run.json")

    if output_path.exists():
        try:
            with output_path.open() as file:
                st.session_state["optimization_result"] = (
                    json.load(file)
                )

            st.success(
                "Previous optimization loaded!"
            )

        except (OSError, ValueError) as error:
            st.error(
                f"Could not load optimization: {error}"
            )

    else:
        st.warning(
            "No previous optimization results found."
        )


# -------------------------------------------------
# OPTIMIZATION RESULTS
# -------------------------------------------------

optimization_result = st.session_state.get(
    "optimization_result"
)

if optimization_result is not None:

    history = optimization_result["history"]

    baseline_metrics = history[0]["metrics"]
    best_metrics = optimization_result["best_metrics"]

    baseline_config = history[0]["config"]
    best_config = optimization_result["best_config"]

    st.divider()
    st.subheader("Optimization Results")

    baseline_score = baseline_metrics["score"]
    best_score = best_metrics["score"]

    baseline_cost = baseline_metrics["sensor_cost_units"]
    best_cost = best_metrics["sensor_cost_units"]

    baseline_delay = baseline_metrics.get(
        "mean_detection_delay_s"
    )
    best_delay = best_metrics.get(
        "mean_detection_delay_s"
    )

    # Performance metrics
    col1, col2, col3 = st.columns(3)

    col1.metric(
        "Best Score",
        f"{best_score:.2f}",
        delta=f"{best_score - baseline_score:+.2f}",
    )

    col2.metric(
        "Fault Recall",
        f"{best_metrics['fault_recall']:.1%}",
    )

    col3.metric(
        "Sensor Cost",
        f"{best_cost:.0f}",
        delta=f"{best_cost - baseline_cost:+.0f}",
        delta_color="inverse",
    )

    col4, col5, col6 = st.columns(3)

    col4.metric(
        "Detection Delay",
        (
            f"{best_delay:.2f} s"
            if best_delay is not None
            else "N/A"
        ),
        delta=(
            f"{best_delay - baseline_delay:+.2f} s"
            if best_delay is not None
            and baseline_delay is not None
            else None
        ),
        delta_color="inverse",
    )

    col5.metric(
        "Completed Rounds",
        len(history) - 1,
    )

    accepted_count = sum(
        1 for step in history[1:]
        if step.get("accepted", False)
    )

    col6.metric(
        "Accepted Improvements",
        accepted_count,
    )

    # -------------------------------------------------
    # BEFORE VS AFTER
    # -------------------------------------------------

    st.subheader("Before vs After Optimization")

    comparison = pd.DataFrame(
        {
            "Metric": [
                "Sensor Positions",
                "Sampling Rates (Hz)",
                "Optimization Score",
                "Fault Recall",
                "Sensor Cost",
                "Detection Delay (s)",
            ],
            "Before": [
                str(baseline_config["sensor_positions"]),
                str(baseline_config["sampling_rates_hz"]),
                round(baseline_score, 2),
                f"{baseline_metrics['fault_recall']:.1%}",
                baseline_cost,
                (
                    round(baseline_delay, 2)
                    if baseline_delay is not None
                    else "N/A"
                ),
            ],
            "After": [
                str(best_config["sensor_positions"]),
                str(best_config["sampling_rates_hz"]),
                round(best_score, 2),
                f"{best_metrics['fault_recall']:.1%}",
                best_cost,
                (
                    round(best_delay, 2)
                    if best_delay is not None
                    else "N/A"
                ),
            ],
        }
    )

    st.dataframe(
        comparison,
        hide_index=True,
        use_container_width=True,
    )

    # -------------------------------------------------
    # OPTIMIZATION PROGRESS
    # -------------------------------------------------

    st.subheader("Optimization Progress")

    progress_rows = []

    for step in history:
        progress_rows.append(
            {
                "Round": step["round"],
                "Candidate Score": step["metrics"]["score"],
                "Best Score": step["best_score"],
            }
        )

    progress_df = pd.DataFrame(progress_rows)

    progress_chart = px.line(
        progress_df,
        x="Round",
        y=["Candidate Score", "Best Score"],
        markers=True,
        title="Candidate vs Best Score",
        labels={
            "value": "Optimization Score",
            "variable": "Metric",
        },
    )

    st.plotly_chart(
        progress_chart,
        use_container_width=True,
    )

    # -------------------------------------------------
    # AGENT DECISION TIMELINE
    # -------------------------------------------------

    st.divider()
    st.subheader("Agent Decision Timeline")

    st.write(
        "Explore how SensorScout's agents investigated "
        "weaknesses and evaluated each experiment."
    )

    for step in history[1:]:

        round_number = step["round"]
        accepted = step.get("accepted", False)

        status = (
            "ACCEPTED"
            if accepted
            else "REJECTED"
        )

        with st.expander(
            f"Round {round_number} — {status}",
            expanded=(round_number == 1),
        ):

            challenge = step.get("challenge", {})
            diagnosis = step.get("diagnosis", {})
            decision = step.get("decision", {})

            st.markdown("#### 1. Challenger Agent")

            st.write(
                challenge.get(
                    "reason",
                    "Investigated monitoring weaknesses.",
                )
            )

            weak_position = challenge.get(
                "target_position"
            )

            if weak_position is not None:
                st.info(
                    f"Investigated sensor location: "
                    f"{weak_position}"
                )

            st.markdown("#### 2. Diagnosis Agent")

            st.write(
                diagnosis.get(
                    "recommendation",
                    "Analyzed the monitoring weakness.",
                )
            )

            st.markdown("#### 3. Designer / Experiment Search")

            source = step.get(
                "proposal_source",
                "unknown",
            )

            st.write(
                f"Selected proposal source: **{source}**"
            )

            if source == "targeted_search":
                st.caption(
                    "This configuration was selected by "
                    "simulation-guided search, not generated "
                    "by the external LLM."
                )

            elif source == "rule_based_designer":
                st.caption(
                    "This configuration was proposed by "
                    "the local rule-based Designer."
                )

            
            sensor_positions = step["config"]["sensor_positions"]
            sampling_rates = step["config"]["sampling_rates_hz"]

            sensor_table = pd.DataFrame({
                "Sensor": [
                    f"Sensor {i + 1}"
                    for i in range(len(sensor_positions))
                ],
                "Position": sensor_positions,
                "Sampling Rate (Hz)": sampling_rates,
            })

            st.markdown("**Proposed Sensor Configuration**")
            st.dataframe(
                sensor_table,
                hide_index=True,
                use_container_width=True,
            )


            st.markdown("#### 4. Strategist Agent")

            st.write(
                decision.get(
                    "reason",
                    "Evaluated the candidate configuration.",
                )
            )

            candidate_metrics = step["metrics"]

            m1, m2, m3 = st.columns(3)

            m1.metric(
                "Candidate Score",
                f"{candidate_metrics['score']:.2f}",
            )

            m2.metric(
                "Fault Recall",
                f"{candidate_metrics['fault_recall']:.1%}",
            )

            m3.metric(
                "Sensor Cost",
                f"{candidate_metrics['sensor_cost_units']:.0f}",
            )

            if accepted:
                st.success(
                    "Strategist accepted this configuration."
                )
            else:
                st.warning(
                    "Strategist rejected this configuration."
                )

    # -------------------------------------------------
    # BLIND SPOT HUNTER
    # -------------------------------------------------

    st.divider()
    st.subheader("Blind Spot Hunter")

    st.write(
        "SensorScout examines fault detection performance "
        "at each of the eight simulated machine locations."
    )

    scenario_results = best_metrics.get(
        "scenario_results",
        [],
    )

    location_rows = []

    for position in range(8):

        scenarios = [
            scenario
            for scenario in scenario_results
            if scenario.get("fault_position") == position
            and scenario.get("fault_type") != "healthy"
        ]

        detected_delays = [
            scenario["detection_delay_s"]
            for scenario in scenarios
            if scenario.get("detected")
            and scenario.get("detection_delay_s") is not None
        ]

        missed_faults = sum(
            1 for scenario in scenarios
            if not scenario.get("detected", False)
        )

        average_delay = (
            sum(detected_delays) / len(detected_delays)
            if detected_delays
            else None
        )

        location_rows.append(
            {
                "Position": position,
                "Average Delay (s)": average_delay,
                "Missed Faults": missed_faults,
            }
        )

    location_df = pd.DataFrame(location_rows)

    if not location_df.empty:

        delay_chart = px.bar(
            location_df,
            x="Position",
            y="Average Delay (s)",
            title="Detection Delay by Fault Location",
        )

        st.plotly_chart(
            delay_chart,
            use_container_width=True,
        )

        st.subheader("Location Analysis")

        st.dataframe(
            location_df,
            hide_index=True,
            use_container_width=True,
        )

        valid_delays = location_df.dropna(
            subset=["Average Delay (s)"]
        )

        if not valid_delays.empty:

            worst_location = valid_delays.loc[
                valid_delays["Average Delay (s)"].idxmax()
            ]

            st.warning(
                "Slowest detected-fault location: "
                f"Position {int(worst_location['Position'])}, "
                f"average delay "
                f"{worst_location['Average Delay (s)']:.2f} s."
            )

    st.caption(
        "All results come from simulated validation "
        "scenarios. The fastest or cheapest configuration "
        "is not necessarily the highest-scoring one."
    )

    with st.expander("View Complete Optimization Data"):
        st.json(optimization_result)


# ============================================================
# FEEDBACK-DRIVEN LEARNING DASHBOARD
# ============================================================

st.divider()
st.header("Feedback-Driven Learning")

st.write(
    "SensorScout remembers previously tested sensor layouts, "
    "analyzes why experiments failed, and adapts its search "
    "strategy in later optimization rounds."
)

st.caption(
    "This is a rule-based feedback-driven optimization system. "
    "It uses simulated experiments and does not retrain a "
    "machine-learning model or call an external LLM."
)

learning_result = st.session_state.get("optimization_result")

if learning_result is None:
    st.info(
        "Run Agent Optimization above to view the learning history."
    )

else:
    learning_history = learning_result.get("history", [])
    experiment_log = learning_result.get("experiment_log", [])

    has_feedback_data = (
        "total_evaluations" in learning_result
        and "unique_configurations_tested" in learning_result
    )

    if not has_feedback_data:
        st.info(
            "These results were saved before feedback tracking "
            "was added. Click Run Agent Optimization to generate "
            "a new learning history."
        )

    else:
        # ----------------------------------------------------
        # EXPERIMENT MEMORY METRICS
        # ----------------------------------------------------

        st.subheader("Experiment Memory")

        total_evaluations = learning_result.get(
            "total_evaluations", 0
        )

        unique_configs = learning_result.get(
            "unique_configurations_tested", 0
        )

        skipped_duplicates = sum(
            step.get("skipped_duplicates", 0)
            for step in learning_history[1:]
        )

        accepted_rounds = sum(
            1
            for step in learning_history[1:]
            if step.get("accepted", False)
        )

        m1, m2, m3, m4 = st.columns(4)

        m1.metric(
            "Total Evaluations",
            total_evaluations,
        )

        m2.metric(
            "Unique Configurations",
            unique_configs,
        )

        m3.metric(
            "Duplicates Avoided",
            skipped_duplicates,
        )

        m4.metric(
            "Accepted Rounds",
            accepted_rounds,
        )

        st.caption(
            "Total evaluations include the baseline. "
            "Duplicates avoided counts configurations skipped "
            "because they were previously evaluated or selected."
        )

        # ----------------------------------------------------
        # ROUND-BY-ROUND STRATEGY
        # ----------------------------------------------------

        st.subheader("Learning Across Rounds")

        learning_rows = []

        for step in learning_history[1:]:
            learning_rows.append({
                "Round": step.get("round"),
                "Strategy": step.get(
                    "strategy", "unknown"
                ),
                "New Evaluations": step.get(
                    "evaluations", 0
                ),
                "Duplicates Skipped": step.get(
                    "skipped_duplicates", 0
                ),
                "Accepted": (
                    "Yes"
                    if step.get("accepted", False)
                    else "No"
                ),
                "Best Score": round(
                    step.get("best_score", 0), 4
                ),
            })

        if learning_rows:
            learning_df = pd.DataFrame(learning_rows)

            st.dataframe(
                learning_df,
                hide_index=True,
                use_container_width=True,
            )

            # Strategy timeline
            strategy_chart = px.scatter(
                learning_df,
                x="Round",
                y="Strategy",
                size="New Evaluations",
                color="Accepted",
                title="Search Strategy by Optimization Round",
                hover_data=[
                    "Duplicates Skipped",
                    "Best Score",
                ],
            )

            st.plotly_chart(
                strategy_chart,
                use_container_width=True,
            )

            evaluation_chart = px.bar(
                learning_df,
                x="Round",
                y=[
                    "New Evaluations",
                    "Duplicates Skipped",
                ],
                barmode="group",
                title="New Experiments vs Duplicate Candidates",
            )

            st.plotly_chart(
                evaluation_chart,
                use_container_width=True,
            )

        # ----------------------------------------------------
        # REJECTION FEEDBACK
        # ----------------------------------------------------

        st.subheader("Why Experiments Failed")

        rejection_summary = learning_result.get(
            "rejection_summary", {}
        )

        if rejection_summary:
            rejection_df = pd.DataFrame([
                {
                    "Rejection Reason": reason,
                    "Count": count,
                }
                for reason, count
                in rejection_summary.items()
            ])

            rejection_df = rejection_df.sort_values(
                "Count",
                ascending=False,
            )

            st.dataframe(
                rejection_df,
                hide_index=True,
                use_container_width=True,
            )

            rejection_chart = px.bar(
                rejection_df,
                x="Count",
                y="Rejection Reason",
                orientation="h",
                title="Experiment Rejection Reasons",
            )

            st.plotly_chart(
                rejection_chart,
                use_container_width=True,
            )

        else:
            st.success(
                "No rejected experiments were recorded."
            )

        # ----------------------------------------------------
        # FEEDBACK EXPLANATIONS
        # ----------------------------------------------------

        st.subheader("How Feedback Changed the Search")

        strategy_explanations = {
            "balanced": (
                "Explore both sampling-rate adjustments "
                "and sensor relocations."
            ),
            "delay_focused": (
                "Prioritize higher sampling rates to "
                "investigate faster fault detection."
            ),
            "recall_aware": (
                "Prioritize alternative sensor placements "
                "after experiments lose fault recall."
            ),
            "cost_aware": (
                "Prioritize lower sampling rates after "
                "experiments exceed the cost limit."
            ),
            "explore": (
                "Try a wider variety of configurations "
                "to investigate new possibilities."
            ),
        }

        for step in learning_history[1:]:
            round_number = step.get("round")
            strategy = step.get("strategy", "unknown")

            with st.expander(
                f"Round {round_number}: "
                f"{strategy.replace('_', ' ').title()}"
            ):
                st.write(
                    strategy_explanations.get(
                        strategy,
                        "Search strategy recorded.",
                    )
                )

                st.write(
                    step.get(
                        "feedback",
                        "No feedback summary available.",
                    )
                )

                round_rejections = step.get(
                    "rejection_reasons", {}
                )

                if round_rejections:
                    st.markdown(
                        "**Rejections during this round:**"
                    )

                    for reason, count in (
                        round_rejections.items()
                    ):
                        st.write(
                            f"- {reason}: {count}"
                        )

                if step.get("accepted", False):
                    st.success(
                        "An improved configuration "
                        "was accepted in this round."
                    )
                else:
                    st.warning(
                        "No new configuration was accepted. "
                        "The best previously accepted "
                        "configuration was preserved."
                    )

        # ----------------------------------------------------
        # INDIVIDUAL EXPERIMENT LOG
        # ----------------------------------------------------

        st.subheader("Experiment Explorer")

        if experiment_log:
            experiment_rows = []

            for index, experiment in enumerate(
                experiment_log, start=1
            ):
                metrics = experiment.get("metrics", {})
                candidate = experiment.get("config", {})

                experiment_rows.append({
                    "Experiment": index,
                    "Round": experiment.get("round"),
                    "Strategy": experiment.get(
                        "strategy", ""
                    ),
                    "Source": experiment.get(
                        "source", ""
                    ),
                    "Positions": str(
                        candidate.get(
                            "sensor_positions", []
                        )
                    ),
                    "Rates (Hz)": str(
                        candidate.get(
                            "sampling_rates_hz", []
                        )
                    ),
                    "Score": round(
                        metrics.get("score", 0), 4
                    ),
                    "Recall": metrics.get(
                        "fault_recall", 0
                    ),
                    "Delay (s)": metrics.get(
                        "mean_detection_delay_s"
                    ),
                    "Cost": metrics.get(
                        "sensor_cost_units"
                    ),
                    "Passed Acceptance Rules": (
                        experiment.get(
                            "accepted", False
                        )
                    ),
                    "Reason": experiment.get(
                        "reason", ""
                    ),
                })

            experiment_df = pd.DataFrame(
                experiment_rows
            )

            st.dataframe(
                experiment_df,
                hide_index=True,
                use_container_width=True,
            )

            st.download_button(
                "Download Experiment History (CSV)",
                data=experiment_df.to_csv(
                    index=False
                ),
                file_name=(
                    "sensorscout_experiment_history.csv"
                ),
                mime="text/csv",
            )

            st.caption(
                "Passing acceptance rules means a candidate "
                "was eligible for selection; it does not mean "
                "it became the final accepted configuration."
            )

        else:
            st.info(
                "No individual experiment history "
                "is available."
            )

        st.caption(
            "All experiments use simulated validation "
            "scenarios. Performance on independent held-out "
            "scenarios has not yet been demonstrated."
        )
